function _opsGuestCore(s) {
  // Hosthub labels extra nights "extend Maria" / "παράταση …". Strip that
  // keyword so the leftover name can still match the same person.
  return _opsNorm(s)
    .replace(/\b(extend(ed|s|ing)?|extension)\b/g, ' ')
    .replace(/παρ[αά]ταση/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function _opsSameGuest(a, b) {
  function prefixMatch(x, y) {
    if (!x || !y) return false;
    if (x === y) return true;
    const shorter = x.length <= y.length ? x : y, longer = x.length <= y.length ? y : x;
    if (shorter.length < 8) return false;
    return longer.indexOf(shorter) === 0 && /[\s\-]/.test(longer.charAt(shorter.length));
  }
  const x = _opsNorm(a), y = _opsNorm(b);
  if (prefixMatch(x, y)) return true;
  const xc = _opsGuestCore(a), yc = _opsGuestCore(b);
  return prefixMatch(xc, yc);
}
function _opsKindHit(k, name) {
  if (!k || !k.re) return false;
  k.re.lastIndex = 0;
  return k.re.test(String(name || ''));
}
// Classify one row from the outgoing and incoming bookings.
// EXTENDED means no turnover today — same guest continuing. A Hosthub checkout
// named "extend Maria" only means THAT stay was extra nights; if a different
// guest arrives the same day it is a real clean (Resilience 21 Aug 2026).
function _opsClassify(outName, inName) {
  const flags = { isExtended: false, isPreparation: false, isMaintenance: false, isOwner: false };
  flags.isOwner = OPS_OWNER_RE.test(String(inName || ''));   // arrivals only
  for (let i = 0; i < OPS_KINDS.length; i++) {
    const k = OPS_KINDS[i];
    if (k.key === 'isExtended') continue;
    if (_opsKindHit(k, inName) || _opsKindHit(k, outName)) { flags[k.key] = true; return flags; }
  }
  const extKind = OPS_KINDS.filter(function (k) { return k.key === 'isExtended'; })[0];
  const inExt = _opsKindHit(extKind, inName);
  if (inExt) flags.isExtended = true;
  else if (outName && inName && _opsSameGuest(outName, inName)) flags.isExtended = true;
  return flags;
}
